import Foundation

/// A tournament or league from `Catalog/competitions.json` (generated by `Tools/teams/tournaments/build_tournaments.py`, see
/// docs/TOURNAMENTS.md). The id is the schedule key: the ESPN league path where ESPN has the competition, the schedule pack's
/// league otherwise, so `LocalSchedule` and `PackStore` find its games by the same string.
struct Competition: Codable, Identifiable, Hashable, Sendable {
    var id: String
    var name: String
    var aliases: [String] = []
    var sport: String
    /// "men", "women" or "mixed".
    var gender: String
    /// "national" (countries) or "club".
    var kind: String
    var level: String?
    var governingBody: String?
    var cadence: String?
    var lastEdition: Edition?
    var nextEdition: Edition?
    var feed: Feed = Feed()
    var teamIds: [String] = []
    /// True when the sides are countries: one team per country and gender, merged across competitions.
    var national: Bool?

    struct Edition: Codable, Hashable, Sendable {
        var year: Int?
        /// "2027-08-27/2027-09-12", "2027-11" or nil.
        var dates: String?
        var host: String?
        var hosts: [String]?
        var champion: String?
        var note: String?

        init(from decoder: Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            year = try? c.decode(Int.self, forKey: .year)
            dates = try? c.decode(String.self, forKey: .dates)
            host = try? c.decode(String.self, forKey: .host)
            hosts = try? c.decode([String].self, forKey: .hosts)
            champion = try? c.decode(String.self, forKey: .champion)
            note = try? c.decode(String.self, forKey: .note)
        }
    }

    /// Where its games come from: `espn` is an ESPN league path (nil: not on ESPN), `pack` a downloadable schedule pack, `held`
    /// says the pack exists but is not published yet.
    struct Feed: Codable, Hashable, Sendable {
        var espn: String?
        var pack: String?
        var held: Bool?
        init() {}
        init(from decoder: Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            espn = try? c.decode(String.self, forKey: .espn)
            pack = try? c.decode(String.self, forKey: .pack)
            held = try? c.decode(Bool.self, forKey: .held)
        }
    }

    var isNational: Bool { national ?? (kind == "national") }
    var isWomen: Bool { gender == "women" }
    var sportValue: Sport? { Sport(rawValue: sport) }

    /// The schedule keys this competition's games are filed under: its id, and ESPN's path when that differs (the women's
    /// basketball World Cup is `basketball/fiba` on ESPN).
    var scheduleKeys: [String] {
        var out = [id]
        if let espn = feed.espn, espn != id { out.append(espn) }
        return out
    }

    /// True when only a downloaded pack can answer for this competition: ESPN does not list it.
    var packOnly: Bool { feed.espn == nil }

    /// Whether any schedule source is known for it at all (ESPN, a pack, held or not).
    var hasScheduleSource: Bool { feed.espn != nil || feed.pack != nil }

    /// "FIBA World Cup 2027" for the next edition, or just the name when no year is known.
    var nextTitle: String { nextEdition?.year.map { "\(name) \($0)" } ?? name }

    /// "Aug 27 \u{2013} Sep 12, 2027 \u{00B7} Qatar", "2029", or nil when nothing is announced.
    var nextLine: String? {
        guard let next = nextEdition else { return nil }
        var parts: [String] = []
        if let dates = next.dates, let text = Self.dateRange(dates) { parts.append(text) } else if let year = next.year { parts.append("\(year)") }
        if let hosts = next.hosts, !hosts.isEmpty { parts.append(hosts.prefix(2).joined(separator: ", ")) }
        return parts.isEmpty ? nil : parts.joined(separator: " \u{00B7} ")
    }

    static func dateRange(_ text: String) -> String? {
        let parse = DateFormatter()
        parse.locale = Locale(identifier: "en_US_POSIX")
        parse.timeZone = TimeZone(identifier: "UTC")
        let out = DateFormatter()
        out.locale = Locale(identifier: "en_US")
        out.timeZone = TimeZone(identifier: "UTC")
        let ends = text.split(separator: "/").map(String.init)
        if ends.count == 2 {
            parse.dateFormat = "yyyy-MM-dd"
            guard let a = parse.date(from: ends[0]), let b = parse.date(from: ends[1]) else { return nil }
            out.dateFormat = "MMM d"
            let cal = Calendar(identifier: .gregorian)
            let sameYear = cal.component(.year, from: a) == cal.component(.year, from: b)
            out.dateFormat = sameYear ? "MMM d" : "MMM d, yyyy"
            let first = out.string(from: a)
            out.dateFormat = "MMM d, yyyy"
            return "\(first) \u{2013} \(out.string(from: b))"
        }
        parse.dateFormat = "yyyy-MM-dd"
        if let d = parse.date(from: text) { out.dateFormat = "MMM d, yyyy"; return out.string(from: d) }
        parse.dateFormat = "yyyy-MM"
        if let d = parse.date(from: text) { out.dateFormat = "MMM yyyy"; return out.string(from: d) }
        return nil
    }
}

/// The competitions of the catalog, loaded once.
final class CompetitionCatalog: @unchecked Sendable {
    static let shared = CompetitionCatalog(bundle: Bundle(for: BundleToken.self))
    private final class BundleToken {}

    let all: [Competition]
    private let byId: [String: Competition]
    private let byKey: [String: Competition]
    private let byAlias: [String: Competition]
    private let byTeam: [String: [Competition]]

    /// The league group names of the teams file that hold one country each, with the gender of the sides in them. A team in one
    /// of them is a national side, whatever its sport.
    static let nationalGroups: [String: String] = [
        "National teams": "men", "Women's national teams": "women",
        "FIBA national teams (men)": "men", "FIBA national teams (women)": "women",
        "IIHF national teams (men)": "men", "IIHF national teams (women)": "women",
        "Handball national teams (men)": "men", "Handball national teams (women)": "women",
        "WBSC national teams (baseball)": "men",
    ]

    init(bundle: Bundle) {
        var list: [Competition] = []
        if let url = bundle.url(forResource: "competitions", withExtension: "json", subdirectory: "Catalog")
            ?? bundle.url(forResource: "competitions", withExtension: "json"),
           let data = try? Data(contentsOf: url),
           let decoded = try? JSONDecoder().decode([Competition].self, from: data) {
            list = decoded
        } else {
            print("Missing bundled Catalog/competitions.json")
        }
        all = list
        byId = Dictionary(list.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })
        var keys: [String: Competition] = byId
        for c in list { for k in c.scheduleKeys where keys[k] == nil { keys[k] = c } }
        byKey = keys
        var aliases: [String: Competition] = [:]
        for c in list {
            for name in [c.name] + c.aliases { aliases[Self.fold(name) + "|" + c.sport + "|" + c.gender] = aliases[Self.fold(name) + "|" + c.sport + "|" + c.gender] ?? c }
        }
        byAlias = aliases
        var teams: [String: [Competition]] = [:]
        for c in list { for id in c.teamIds { teams[id, default: []].append(c) } }
        byTeam = teams
    }

    /// A competition by its id or its ESPN path.
    func competition(_ key: String?) -> Competition? { key.flatMap { byKey[$0] } }

    /// A competition by a name people use for it ("World Cup", "EuroBasket"): the id first, then the name and aliases within a
    /// sport and gender. Without a sport the first competition with that name wins.
    func competition(named name: String, sport: Sport? = nil, gender: String? = nil) -> Competition? {
        if let hit = byKey[name] { return hit }
        let folded = Self.fold(name)
        for g in gender.map({ [$0] }) ?? ["men", "women", "mixed"] {
            for s in sport.map({ [$0.rawValue] }) ?? Sport.allCases.map(\.rawValue) {
                if let hit = byAlias[folded + "|" + s + "|" + g] { return hit }
            }
        }
        return nil
    }

    /// The competitions a catalog team plays in, the ones with a date first (soonest edition), national before club.
    func competitions(forTeam id: String) -> [Competition] {
        (byTeam[id] ?? []).sorted { a, b in
            let ya = a.nextEdition?.year ?? .max, yb = b.nextEdition?.year ?? .max
            if ya != yb { return ya < yb }
            let da = a.nextEdition?.dates ?? "~", db = b.nextEdition?.dates ?? "~"
            if da != db { return da < db }
            return a.name < b.name
        }
    }

    /// The catalog teams of a competition.
    @MainActor func teams(in id: String, library: Library) -> [Team] {
        (competition(id)?.teamIds ?? []).compactMap { library.teams[$0] }
    }

    /// Whether a schedule key is a competition between countries.
    func isNational(_ key: String?) -> Bool { competition(key)?.isNational ?? false }

    /// "men" or "women" for a schedule key the catalog knows.
    func gender(of key: String?) -> String? { competition(key)?.gender }

    /// The national competitions of a sport and gender, as schedule keys to ask (id and ESPN path), soonest edition first.
    func nationalKeys(sport: Sport, gender: String) -> [String] {
        var out: [String] = []
        for c in all where c.isNational && c.sport == sport.rawValue && c.gender == gender {
            for k in c.scheduleKeys where !out.contains(k) { out.append(k) }
        }
        return out
    }

    /// The schedule keys of a national team's competitions: those that list it, else every national competition of its sport
    /// and gender (a country the lists miss still plays friendlies).
    func nationalKeys(for team: Team) -> [String] {
        guard let gender = Self.nationalGender(of: team) else { return [] }
        let own = competitions(forTeam: team.id).filter(\.isNational)
        guard !own.isEmpty else { return nationalKeys(sport: team.sport, gender: gender) }
        var out: [String] = []
        for c in own { for k in c.scheduleKeys where !out.contains(k) { out.append(k) } }
        return out
    }

    /// Whether the key is a competition whose games ESPN does not serve under that key: it has no ESPN feed (FIBA, IIHF, IHF
    /// tournaments), or ESPN files it under another path (`basketball/fiba` for the women's basketball World Cup). A downloaded
    /// schedule pack, keyed by the competition id, is then the source for it.
    func isPackOnly(_ key: String) -> Bool {
        guard let c = byId[key] else { return false }
        return c.feed.espn != key
    }

    // MARK: National sides

    static func nationalGender(of team: Team) -> String? { nationalGroups[team.league] }
    static func isNationalSide(_ team: Team) -> Bool { nationalGroups[team.league] != nil }

    /// A national group split by continental championship (FIBA Europe, Americas, Africa, Asia for basketball), when those
    /// championships between them hold almost every team of the group; nil when they do not (soccer, hockey).
    func zones(for teams: [Team]) -> [(title: String, teams: [Team])]? {
        guard let first = teams.first, let gender = Self.nationalGender(of: first), teams.count > 40 else { return nil }
        let ids = Set(teams.map(\.id))
        var seenBodies = Set<String>()
        var claimed = Set<String>()
        var out: [(title: String, teams: [Team])] = []
        let continental = all.filter { $0.isNational && $0.level == "continental" && $0.sport == first.sport.rawValue && $0.gender == gender }
        for c in continental {
            guard let body = c.governingBody, seenBodies.insert(body).inserted else { continue }
            let members = teams.filter { ids.contains($0.id) && c.teamIds.contains($0.id) && !claimed.contains($0.id) }
            guard !members.isEmpty else { continue }
            claimed.formUnion(members.map(\.id))
            out.append((body, members))
        }
        guard Double(claimed.count) >= 0.9 * Double(teams.count), out.count >= 2 else { return nil }
        let rest = teams.filter { !claimed.contains($0.id) }
        if !rest.isEmpty { out.append(("Other", rest)) }
        return out.sorted { $0.teams.count > $1.teams.count }
    }

    static func fold(_ s: String) -> String {
        String(s.folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .init(identifier: "en_US"))
            .map { $0.isLetter || $0.isNumber ? $0 : " " }).split(separator: " ").joined(separator: " ")
    }
}
